        void draw(int whole){draws++;if(beforeDraw!=null)beforeDraw.accept(this);if(!skipQueue){var b=get(whole);last=queue.drawObject(new DrawCallCut(new CdSlotRef(whole),b.unsignedByte(1),b.unsignedWord(8),b.unsignedWord(12),b.unsignedByte(0x16),b.unsignedByte(0x19),b.unsignedByte(0x18)),new CameraWords(0,0));}if(afterDraw!=null)afterDraw.accept(this);}
        @Override public LiveDrawSlot read(CdSlotRef ref){var b=get(ref.wholeIndex());return new LiveDrawSlot(b.unsignedByte(0),b.unsignedByte(1),b.unsignedWord(8),b.unsignedWord(12),b.unsignedWord(10),(int)b.unsignedLong(4),b.unsignedByte(0x1A),b.unsignedWord(2));}
