    private static int index(int whole){if(whole<1||whole>31)throw new IllegalArgumentException("reserved1..31");return whole-1;}
    private static List<CdSlotRef> refs(){return List.of(new CdSlotRef(2),new CdSlotRef(3),new CdSlotRef(5),new CdSlotRef(31));}
    private static DrawCameras cameras(){return new DrawCameras(new CameraWords(0x6000,0x7000),new CameraWords(0x1234,0x4321),new CameraWords(0x8000,0xFFFF));}
