    private static byte[] image(int id,int routine,int subtype,int subtype2,int flags){var b=new byte[64];for(int i=0;i<64;i++)b[i]=(byte)(0x43+i*13);b[0]=(byte)id;b[1]=(byte)flags;b[0x24]=(byte)routine;b[0x28]=(byte)subtype;b[0x29]=(byte)subtype2;return b;}
    private static byte[] hud(byte[] in){var b=in.clone();b[0x24]=2;longWord(b,4,0x20ABBE);word(b,2,0x8568);word(b,8,0x90);word(b,10,0x88);return b;}
    private static byte[] icon(byte[] in){var b=in.clone();b[0x24]=2;longWord(b,4,0x20A8A6);word(b,2,0x85A8);word(b,8,0xC4);word(b,10,0x152);return b;}
    private static void word(byte[] b,int at,int v){b[at]=(byte)(v>>>8);b[at+1]=(byte)v;}private static int word(byte[] b,int at){return (Byte.toUnsignedInt(b[at])<<8)|Byte.toUnsignedInt(b[at+1]);}private static void longWord(byte[] b,int at,int v){word(b,at,v>>>16);word(b,at+2,v);}
